```csharp
public class Matrix {
    private readonly double[,] _data;
    public int Rows { get; }
    public int Cols { get; }

    public Matrix(int rows, int cols) {
        Rows = rows;
        Cols = cols;
        _data = new double[rows, cols];
    }

    // 1. INDEXER (Syntaxe speciální vlastnosti se slovem 'this')
    public double this[int row, int col] {
        get {
            return _data[row, col];
        }
        set {
            _data[row, col] = value;
        }
    }

    // 2. PŘETÍŽENÍ OPERÁTORU '+'
    // Operátory MUSÍ být deklarovány jako 'public static'
    public static Matrix operator +(Matrix a, Matrix b) {
        if (a.Rows != b.Rows || a.Cols != b.Cols) {
            throw new ArgumentException('Matice musí mít stejné rozměry.');
        }

        Matrix result = new Matrix(a.Rows, a.Cols);
        for (int i = 0; i < a.Rows; i++) {
            for (int j = 0; j < a.Cols; j++) {
                // Zde využíváme náš vlastní Indexer z bodu 1
                result[i, j] = a[i, j] + b[i, j];
            }
        }
        return result;
    }
}
```

