```csharp
public class NetworkConnection {
    // Konstruktor
    public NetworkConnection() { 
        // Open connection
    }

    // Finalizátor (Destruktor) - začíná vlnovkou, nemá modifikátor přístupu!
    ~NetworkConnection() { 
        // Close connection
    }
