```csharp
public class ThreadRunner {
    // 1. Metoda, kterou budou vlákna vykonávat
    public static void PrintNumbers(int limit) {
        for (int i = 0; i < limit; i++) {
            Console.Write(i + ' ');
        }
    }

    public static void Main() {
        // 2. a 3. Vytvoření vláken pomocí třídy Thread a Lambdy pro předání parametru
        Thread t1 = new Thread(() => PrintNumbers(50));
        Thread t2 = new Thread(() => PrintNumbers(100));

        // Spuštění vláken (Scheduler OS je nyní začne libovolně prokládat)
        t1.Start();
        t2.Start();

        // 4. Vyčkání na dokončení (Main vlákno se zde zablokuje)
        t1.Join();
        t2.Join();

        Console.WriteLine('Všechna vlákna dokončila práci.');
    }
